  assessmentOverview: { formative: ['التحدي السريع بعد كل فصل', 'فحص الدليل ونسبة المصدر ودرجة اليقين', 'الملاحظة والبناء في التركيز اللغوي', 'القراءة الجهرية المضبوطة', 'الفقرة التحليلية في مستوى B2', 'تذاكر الخروج'], summative: ['فحص المعرفة', 'تحدي المفردات', 'مراجعة اللغة التراكمية', 'التحدي النهائي'] },
